3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // invoices references projects references clients, so H2 refuses to TRUNCATE a parent while
36	        // the FK exists — drop referential integrity for the duration, truncate all, then restore.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        try {
39	            jdbc.execute("TRUNCATE TABLE dashboard_reference");
40	            jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
41	            jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
42	            jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
43	            jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
44	            jdbc.execute("TRUNCATE TABLE invoice_payments RESTART IDENTITY");
45	            jdbc.execute("TRUNCATE TABLE invoice_line_items RESTART IDENTITY");
46	            jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
47	            jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
48	            jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
49	            jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
50	        } finally {
51	            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
52	        }
53	    }
54	
55	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
56	    @PostMapping("/seed")
57	    @SuppressWarnings("unchecked")
58	    public void seed(@RequestBody Map<String, Object> fixture) {
59	        // The reference date the dashboard measures "overdue" against (single row, id = 1). Optional:
60	        // a spec that does not care leaves it out, so the dashboard falls back to today.
61	        Object asOf = fixture.get("asOf");
62	        if (asOf != null) {
63	            jdbc.update("INSERT INTO dashboard_reference (id, as_of) VALUES (1, ?)",
64	                    java.sql.Date.valueOf(java.time.LocalDate.parse(asOf.toString())));
65	        }
66	        List<Map<String, Object>> clients =
67	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
68	        // Explicit ids from the fixture (the spec asserts rows by these ids), via JdbcTemplate.
69	        for (Map<String, Object> c : clients) {
70	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
71	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
72	        }
73	        List<Map<String, Object>> projects =
74	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
75	        for (Map<String, Object> p : projects) {
76	            // status is optional in the fixture — a spec that only cares a project exists leaves it
77	            // out, defaulting to ACTIVE (the same state a fresh project gets, V22__project_status.sql).
78	            Object status = p.getOrDefault("status", "ACTIVE");
79	            // archived is optional too — a spec that only cares a project exists leaves it out,
80	            // defaulting to not-archived (the same state a fresh project gets, V16__project_archived.sql).
81	            boolean archived = Boolean.TRUE.equals(p.getOrDefault("archived", Boolean.FALSE));
82	            // budget is optional in the fixture — a spec that does not care about the budget leaves
83	            // it out, so the column stays NULL (the same state a fresh project gets until one is set,
84	            // V23__project_budget.sql).
85	            java.math.BigDecimal budget = p.get("budget") != null
86	                    ? new java.math.BigDecimal(p.get("budget").toString())
87	                    : null;
88	            jdbc.update(
